#!/usr/bin/env node

/**

 * Audit local .env against production-required keys and write hostinger-production.env

 * for hPanel import (gitignored — see .gitignore).

 *

 * Auto-generated INTERNAL_API_SECRET / REVALIDATE_SECRET are printed to console only,

 * never written as values in the output file.

 *

 * Usage: npm run hostinger:env-audit

 */

import { readFileSync, existsSync, writeFileSync } from "node:fs";
import { randomBytes } from "node:crypto";

import { resolve, dirname } from "node:path";

import { fileURLToPath } from "node:url";

import { spawnSync } from "node:child_process";



const __dirname = dirname(fileURLToPath(import.meta.url));

const root = resolve(__dirname, "..");

const outPath = resolve(root, "hostinger-production.env");



const REQUIRED = [

  "NEXT_PUBLIC_APP_URL",

  "APP_BASE_URL",

  "NEXT_PUBLIC_CLERK_PUBLISHABLE_KEY",

  "CLERK_SECRET_KEY",

  "CLERK_WEBHOOK_SIGNING_SECRET",

  "NEXT_PUBLIC_SUPABASE_URL",

  "NEXT_PUBLIC_SUPABASE_ANON_KEY",

  "SUPABASE_SERVICE_KEY",

  "PAYMOB_API_KEY",

  "PAYMOB_INTEGRATION_ID_CARD",

  "PAYMOB_INTEGRATION_ID_WALLET",

  "RESEND_API_KEY",

  "RESEND_FROM_EMAIL",

  "INTERNAL_API_SECRET",

  "REVALIDATE_SECRET",

];



const RECOMMENDED = [

  "COOKIE_BITE_PRIMARY_DOMAIN",

  "GEMINI_API_KEY",

  "MR_BROWNIE_GEMINI_MODEL",

  "NEXT_PUBLIC_SANITY_PROJECT_ID",

  "NEXT_PUBLIC_SANITY_DATASET",

  "SANITY_WEBHOOK_SECRET",

  "PAYMOB_HMAC_SECRET",

  "REDIS_URL",

  "WHATSAPP_CLOUD_API_TOKEN",

  "WHATSAPP_PHONE_NUMBER_ID",

];



const SECRET_KEYS = new Set(["INTERNAL_API_SECRET", "REVALIDATE_SECRET"]);



function loadEnvFile(file) {

  const p = resolve(root, file);

  if (!existsSync(p)) return;

  for (const line of readFileSync(p, "utf8").split(/\r?\n/)) {

    const t = line.trim();

    if (!t || t.startsWith("#")) continue;

    const i = t.indexOf("=");

    if (i < 0) continue;

    const k = t.slice(0, i);

    const v = t.slice(i + 1).replace(/^["']|["']$/g, "");

    if (!(k in process.env)) process.env[k] = v;

  }

}



function hasPaymobHmac() {
  return Boolean(getValue("PAYMOB_HMAC_SECRET") || getValue("PAYMOB_HMAC"));
}



function getValue(key) {

  const v = process.env[key]?.trim();

  if (!v || v.includes("REPLACE_ME") || v.startsWith("__SET_IN_")) return "";

  return v;

}



function suggestSecret() {

  return randomBytes(32).toString("hex");

}



loadEnvFile(".env");

loadEnvFile(".env.local");



const missing = [];

const consoleSecrets = [];

const lines = [

  "# Generated by npm run hostinger:env-audit — import in hPanel then Redeploy",

  "# Do NOT commit this file. Secrets for empty INTERNAL_* / REVALIDATE_* are shown in terminal only.",

  "# Only keys WITH values are exported — empty keys are listed as comments so import does not wipe Hostinger.",

  "",

];



for (const key of REQUIRED) {

  const value = getValue(key);

  if (!value) {

    missing.push(key);

    if (SECRET_KEYS.has(key)) {

      const generated = suggestSecret();

      consoleSecrets.push({ key, value: generated });

      lines.push(`# MISSING ${key} — generated once in terminal; paste into hPanel`);

    } else {

      lines.push(`# MISSING ${key} — set in .env then re-run hostinger:env-audit`);

    }

  } else {

    lines.push(`${key}=${value}`);

  }

}



if (!hasPaymobHmac()) {

  missing.push("PAYMOB_HMAC_SECRET");

  lines.push("# MISSING PAYMOB_HMAC_SECRET — Paymob dashboard → Settings → HMAC secret");

} else {

  const hmac = getValue("PAYMOB_HMAC_SECRET") || getValue("PAYMOB_HMAC");

  lines.push(`PAYMOB_HMAC_SECRET=${hmac}`);

}



lines.push("");

lines.push("# Recommended (optional but useful):");

for (const key of RECOMMENDED) {

  const value = getValue(key);

  if (value) lines.push(`${key}=${value}`);

}



lines.push("");

lines.push("# Cron: POST https://cookie-bite.com/api/cron/notification-jobs");

lines.push("# Header: x-internal-secret: <INTERNAL_API_SECRET>");

lines.push("");

lines.push("# Keep false until all REQUIRED keys above are filled on Hostinger:");

lines.push("COOKIE_BITE_FAIL_ON_MISSING_ENV=false");



writeFileSync(outPath, lines.join("\n") + "\n", "utf8");



console.log("\n=== Hostinger production env audit ===\n");

const paymobMissing = missing.filter((k) => k.startsWith("PAYMOB_"));

if (missing.length) {

  console.log("Missing or empty locally (fix in .env then re-run):");

  for (const k of missing) console.log(`  - ${k}`);

  if (paymobMissing.length) {

    console.log("\nPaymob (accept.paymob.com → Developers / Integrations):");

    console.log("  - PAYMOB_API_KEY          → Secret API key");

    console.log("  - PAYMOB_HMAC_SECRET      → HMAC secret (webhook + intention)");

    console.log("  - PAYMOB_INTEGRATION_ID_CARD   → numeric integration ID");

    console.log("  - PAYMOB_INTEGRATION_ID_WALLET → numeric integration ID");

    console.log("  Webhook: https://cookie-bite.com/api/webhooks/paymob");

  }

} else {

  console.log("All required keys present locally.");

}

if (!hasPaymobHmac()) console.log("  - PAYMOB_HMAC_SECRET (or PAYMOB_HMAC)");



if (consoleSecrets.length) {

  console.log("\n--- One-time generated secrets (copy to .env.local AND hPanel; not saved in file) ---");

  for (const { key, value } of consoleSecrets) {

    console.log(`${key}=${value}`);

  }

  console.log("--- end secrets ---\n");

}



console.log(`Wrote ${outPath}`);

console.log("Next: hPanel → cookie-bite.com → Environment variables → Import → Redeploy");

console.log("Checklist: npm run hostinger:checklist");

console.log("\nProduction probe: https://cookie-bite.com/ should return 200 after redeploy.");



spawnSync(process.execPath, [resolve(__dirname, "hostinger-sync-checklist.mjs")], {

  stdio: "inherit",

  cwd: root,

});



if (missing.length) process.exit(1);

